using RoomCode = std::array<char, 5>;

inline constexpr std::size_t kRoomCodeLength = 5;
inline constexpr char kRoomCodeAlphabet[] = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
inline constexpr std::size_t kRoomCodeAlphabetSize = 32;

// The alphabet deliberately drops I/O/0/1 to avoid look-alike confusion, which
// is exactly what makes 32 symbols fit the five 5-bit groups below.
static_assert(sizeof(kRoomCodeAlphabet) - 1 == kRoomCodeAlphabetSize,
              "room code alphabet must contain exactly 32 symbols");

// Packs five 5-bit groups from the low bits of `word` into a code. All-zero
// input is legal and yields "AAAAA".
inline RoomCode code_from_word(std::uint32_t word) noexcept {
    RoomCode code{};
    for (std::size_t i = 0; i < kRoomCodeLength; ++i) {
        code[i] = kRoomCodeAlphabet[word & 31u];
        word >>= 5;
    }
    return code;
}

struct RoomHandle {
    RoomCode code{};
    std::uint64_t generation = 0;
    std::uint64_t owner = 0;
};

// A live entry owns its payload in the directory until take() transfers it out.
template <class T>
struct RoomEntry {
    RoomHandle handle{};
    T value;
};

std::size_t first_empty_slot_() const {
    for (std::size_t i = 0; i < Capacity; ++i) {
        if (!entries_[i].has_value()) {
            return i;
        }
    }
    return Capacity;
}

std::array<std::optional<RoomEntry<T>>, Capacity> entries_{};
std::size_t count_ = 0;
mutable std::mutex mutex_;
bool closed_ = false;
std::uint64_t next_generation_ = 1;

enum class RoomCreate {
    created,
    closed,
    invalid_owner,
    duplicate_owner,
    generation_exhausted,
    full,
    source_failed,
    collision_limit,
};

struct RoomCreated {
    RoomCreate status = RoomCreate::source_failed;
    std::optional<RoomHandle> handle;
};

template <class Next>
[[nodiscard]] RoomCreated create(std::uint64_t owner, T& value, Next&& next) {
    static_assert(
        std::is_nothrow_invocable_r_v<std::optional<std::uint32_t>, Next&>,
        "next must be a noexcept callable returning optional<uint32_t>");

    std::lock_guard<std::mutex> lock(mutex_);

    if (closed_) {
        return RoomCreated{RoomCreate::closed, std::nullopt};
    }
    if (owner == 0) {
        return RoomCreated{RoomCreate::invalid_owner, std::nullopt};
    }
    if (has_owner_(owner)) {
        return RoomCreated{RoomCreate::duplicate_owner, std::nullopt};
    }
    if (next_generation_ == 0) {
        return RoomCreated{RoomCreate::generation_exhausted, std::nullopt};
    }
    if (count_ >= Capacity) {
        return RoomCreated{RoomCreate::full, std::nullopt};
    }

    for (std::uint32_t attempt = 0; attempt < kRoomCreateAttempts; ++attempt) {
        std::optional<std::uint32_t> word = std::invoke(next);
        if (!word.has_value()) {
            return RoomCreated{RoomCreate::source_failed, std::nullopt};
        }

        const RoomCode candidate = code_from_word(*word);
        if (code_in_use_(candidate)) {
            continue;  // Retry against every live code, not just one slot.
        }

        const std::size_t slot = first_empty_slot_();
        const std::uint64_t generation = next_generation_;
        const RoomHandle handle{candidate, generation, owner};

        entries_[slot].emplace(RoomEntry<T>{handle, std::move(value)});
        ++count_;

        // Never wrap back to 1, which would alias the first generation.
        next_generation_ = (generation == std::numeric_limits<std::uint64_t>::max())
                               ? 0
                               : generation + 1;

        return RoomCreated{RoomCreate::created, handle};
    }

    return RoomCreated{RoomCreate::collision_limit, std::nullopt};
}

[[nodiscard]] std::optional<RoomHandle> find(const RoomCode& code) const {
    std::lock_guard<std::mutex> lock(mutex_);
    for (const auto& slot : entries_) {
        if (slot.has_value() && slot->handle.code == code) {
            return slot->handle;
        }
    }
    return std::nullopt;
}

[[nodiscard]] std::optional<RoomEntry<T>> take(const RoomHandle& handle) {
    std::lock_guard<std::mutex> lock(mutex_);
    for (auto& slot : entries_) {
        if (!slot.has_value()) {
            continue;
        }
        const RoomHandle& current = slot->handle;
        if (current.code != handle.code ||
            current.generation != handle.generation ||
            current.owner != handle.owner) {
            continue;
        }

        std::optional<RoomEntry<T>> result{std::move(slot.value())};
        slot.reset();
        --count_;
        return result;
    }
    return std::nullopt;
}

void close() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (closed_) {
        return;
    }
    closed_ = true;
    for (auto& slot : entries_) {
        slot.reset();
    }
    count_ = 0;
}

auto response_peer = std::make_shared<Peer>(admit(std::move(accepted),host_request));
require(host_request.route == AdmissionRoute::create);
RoomDirectory<std::shared_ptr<Peer>,4> directory;
auto pending = response_peer; // A short-lived owning alias for the response.
auto made = directory.create(101,pending,[]() noexcept -> std::optional<uint32_t> { return 103; });
require(made.status == RoomCreate::created && made.handle && !pending);
Frame info; info.type = 52; info.size = 5;
for (unsigned i = 0; i < 5; ++i) info.payload[i] = static_cast<std::uint8_t>(made.handle->code[i]);
send_frame(response_peer->socket,info); // Advertise only after reservation succeeds.
response_peer.reset(); // Directory now holds the sole shared_ptr to the host Peer.

inline std::optional<RoomCode> parse_room_code(std::string_view text) noexcept {
    if (text.size() != kRoomCodeLength) {
        return std::nullopt;
    }
    RoomCode code{};
    for (std::size_t i = 0; i < kRoomCodeLength; ++i) {
        std::size_t index = kRoomCodeAlphabetSize;
        for (std::size_t j = 0; j < kRoomCodeAlphabetSize; ++j) {
            if (kRoomCodeAlphabet[j] == text[i]) {
                index = j;
                break;
            }
        }
        if (index == kRoomCodeAlphabetSize) {
            return std::nullopt;
        }
        code[i] = text[i];
    }
    return code;
}

const std::string requested(guest_request.room.begin(),guest_request.room.end());
const auto code = parse_room_code(requested); require(bool(code));
const auto handle = directory.find(*code); require(bool(handle));
auto host = directory.take(*handle); require(host && host->handle.owner == 101);
directory.close(); require(!directory.find(*code));

const Frame a = read_frame(*host->value), b = read_frame(guest);
RoundBatch ia,ib; require(decode_round_input(a,ia) && decode_round_input(b,ib));
require(ia.round == 1 && ib.round == 1 && ia.inputs.first_tick == 0 && ib.inputs.first_tick == 0 &&
        ia.inputs.count == 1 && ib.inputs.count == 1);
auto board = study_round::Round::create_seeded(study_grid::Grid{},77); require(bool(board));
const study_combat::Duel duel(*board,*board); RoundPlay left,right;
require(left.prepare(1,duel,Side::host,0) && right.prepare(1,duel,Side::peer,0) && left.start() && right.start());
Frame local_a,local_b;
require(left.capture(ia.inputs.masks[0],local_a).input == Put::stored &&
        right.capture(ib.inputs.masks[0],local_b).input == Put::stored);
require(left.receive(b).input == Put::stored && right.receive(a).input == Put::stored);
require(left.advance() == Advance::advanced && right.advance() == Advance::advanced);
require(snapshot(left) == snapshot(right));

Directory q; auto value = std::make_unique<unsigned>(9);
auto a = q.create(1,value,zero); CHECK(a.handle && !value);
auto taken = q.take(*a.handle); CHECK(taken);
value = std::move(taken->value);
auto b = q.create(1,value,zero); CHECK(b.handle && b.handle->generation != a.handle->generation);
CHECK(!q.take(*a.handle)); // Same visible code and owner; old generation loses.
auto wrong_owner = *b.handle; wrong_owner.owner = 2; CHECK(!q.take(wrong_owner));
